toolCalls.commandLine:
*** Begin Patch
*** Update File: src/styles.css
@@
 .media, .media img { width: 100%; height: 100%; }
+.media { display: block; }
 .media img { object-fit: cover; transition: transform .45s var(--ease), filter .45s; }
@@
 .ov { position: absolute; inset: 0; display: flex; flex-direction: column; justify-content: space-between; padding: 12px; color: #fff; background: linear-gradient(to bottom, rgba(0,0,0,.55), rgba(0,0,0,.05) 36%, rgba(0,0,0,.72)); opacity: 0; transition: opacity .2s; }
 .tile:hover .ov, .tile:focus-within .ov { opacity: 1; }
+.tile .ov { pointer-events: none; }
+.tile:hover .ov, .tile:focus-within .ov { pointer-events: auto; }
@@
   .ov { opacity: 1; padding: 9px; }
+  .tile .ov { pointer-events: auto; }
*** End Patch

